      }
    }
  }

  // Also look for carousel or skin slider
  const skinImages = Array.from(document.querySelectorAll('img')).map(img => ({
    src: img.src,
    alt: img.alt,
    className: img.className
  })).filter(img => img.alt.toLowerCase().includes('ahri') || img.src.toLowerCase().includes('skin') || img.src.toLowerCase().includes('ahri'));

  return { textMatches, skinImages };
});

