const tabId = 1148881640;

const clickResult = await browserjs(tabId, () => {
  const targetLi = document.querySelector('li[aria-label="22 of 22"]');
  if (!targetLi) return { found: false };

  // Check what's inside targetLi
  const clickableChild = targetLi.querySelector('button, [role="button"], div') || targetLi;

  // Also check what the current active/displayed skin is
  const getActiveSkin = () => {
    // Look for active slide or displayed title/image in Available Skins
    const skinsSection = document.querySelector('#available-skins') || Array.from(document.querySelectorAll('*')).find(el => el.innerText?.trim() === 'Available Skins')?.closest('section');
    const displayedSkin = skinsSection?.querySelector('h3, h2, [data-testid="hero-image"], img[class*="fit-"]');
    return {
      displayedImage: displayedSkin?.src,
      activeItem: document.querySelector('li[aria-label*="of 22"][aria-selected="true"], li[aria-label*="of 22"].active, li[aria-label*="of 22"][data-active="true"]')?.getAttribute('aria-label')
    };
  };

  const before = getActiveSkin();
  targetLi.scrollIntoView({ behavior: 'instant', block: 'center', inline: 'center' });
  clickableChild.click();
  const after = getActiveSkin();

  return {
    found: true,
    before,
    after,
    targetText: targetLi.innerText?.trim()
  };
});

console.log(JSON.stringify(clickResult, null, 2));

