  const skinsSection = document.querySelector('#available-skins') || Array.from(document.querySelectorAll('*')).find(el => el.innerText?.trim() === 'Available Skins')?.closest('section');

  // Look for the main splash image in the skins section
  const splashImg = skinsSection.querySelector('img[class*="fit-"]');
  // Check all images in the section with width > 300
  const bigImages = Array.from(skinsSection.querySelectorAll('img')).filter(img => img.offsetWidth > 300 || img.naturalWidth > 500);

  // Let's click the inner element of slide 21
  const slide21 = document.querySelector('li[id="carousel-:R1p5lam:-slide-21"]');
  const innerClickable = slide21?.querySelector('div');

  // Let's simulate clicking innerClickable with MouseEvent
  if (innerClickable) {
    innerClickable.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
  }

  return {
    splashImgSrc: splashImg?.src,
    bigImages: bigImages.map(img => ({ src: img.src, width: img.offsetWidth, height: img.offsetHeight })),
    slide21Active: slide21?.getAttribute('data-slide-active')
  };
});

